
.vip-container {
  background: linear-gradient(to bottom, #23263c, #190f25);
  min-height: 100vh;

  .banner-container {
    background: url("../../assets/vip/banner.png") no-repeat center center;
    background-size: cover;
    margin-bottom: -200px;
    padding-top: 100px;
    padding-bottom: 200px;
    // width: 1920px;
    // height: 450px;
    font-size: 30px;
    background-repeat: no-repeat;
    background-position: center center;
    min-height: 300px;
    display: flex;

    .btn-wrapper {
      width: 95%;
      max-width: 1400px;
      margin: auto;
      position: relative;

      .center {
        text-transform: uppercase;
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        text-align: center;
        color: #ffffff;

        .page-headline {
          font-size: 150px;
          line-height: 150px;
          font-family: Wave;
        }

        .page-subline {
          font-size: 25px;
          line-height: 25px;
          margin-bottom: 20px;
          font-family: Wave;
        }

        .page-blend {
          background-image: linear-gradient(to right, #de4545, #db7e42);
          font-family: Wave;
          color: #ffffff;
          font-size: 60px;
          line-height: 60px;
          padding: 15px;
          border-radius: 20px;
          margin-bottom: 10px;
          width: 100%;
          max-width: 460px;

          .pesos {
            font-family: sans-serif;
            font-weight: bold;
          }
        }

        .page-liner {
          font-size: 20px;
          text-transform: none;
        }

        img {
          max-width: unset;
        }

        .common-btn.getnow {
          background: #ffffff;
          color: #000000;
          border: transparent;

          &:hover {
            background: #ffd800;
          }
        }
      }
    }

    // .jp-container {
    //   display: flex;
    //   justify-content: center;
    //   text-align: center;
    //   font-size: 110px;
    //   margin-top: 30px;
    //   color: #1bcef1;
    //   font-family: jp;
    //   font-weight: 600;
    //   line-height: 120px;

    //   .jp-number-item {
    //     width: 96px;
    //     height: 120px;
    //     // background-image: url("../../assets/images/games/casino/jp_bg.png");
    //     background-repeat: no-repeat;
    //     background-size: 100% 100%;
    //   }
    // }
  }

  .inner-vip-mobile {
    display: none;
  }

  .vipitem {
    position: relative;
    display: flex;
    flex-direction: column-reverse;
    background: url("../../assets/vip/vip_04.png") no-repeat top center;
    background-size: contain;
    width: 350px;
    min-height: 410px;
    justify-content: flex-end;

    .viplevelcircle {
      img {
        width: 140px;
        margin-top: 20px;
      }

      margin-bottom: -50px;
      z-index: 1;
    }

    .vipcontents {
      padding-top: 60px;
      // background: #2b2b4b;
      color: #ffffff;
      border-radius: 20px;
      display: flex;
      justify-content: center;
      align-items: center;
      flex-direction: column;
      // border-top: 2px solid #db7e42;
      // border-bottom: 2px solid #db7e42;
      .title {
        font-size: 18px;
        line-height: 36px;
      }

      .inner-vip {
        background-color: #303450;
        width: 100%;
        margin-bottom: 10px;
        display: flex;
        justify-content: space-evenly;
        font-size: 45px;
        line-height: 53px;
        font-family: "Arial";
      }

      .second-vip {
        // background: #2b2b4b;
        width: 100%;
        display: flex;
        justify-content: space-around;
        font-size: 45px;
        line-height: 53px;

        div {
          flex: 1;
        }

        .common-btn {
          padding: 5px 10px;
          font-size: 12px;
          line-height: 20px;
          margin: 0 30px 30px;
        }
      }
    }
  }

  .vip-program {
    .game-title {
      margin-bottom: 30px;
    }

    margin: 50px auto;
    max-width: 1080px;
    width: 95%;

    .buttons {
      display: flex;
      justify-content: center;
      align-items: stretch;
      border: 1px solid #db7e42;
      border-radius: 10px;
      margin-bottom: 10px;

      .common-btn {
        display: block;
        width: 100%;
        text-align: center;
        background: transparent;

        &.active {
          background-image: linear-gradient(to right, #de4545, #db7e42);
        }
      }
    }

    :deep(.ant-table-thead > tr > th) {
      text-align: center;

      &:nth-child(odd) {
        background: #2b2b4b;
      }
    }

    :deep(.ant-table-tbody > tr > td) {
      &:nth-child(odd) {
        background: #2b2b4b;
      }
    }

    .note {
      color: #db7d42;
      margin-top: 5px;
      display: block;
    }
  }

  .terms-conditions {
    padding-bottom: 80px;
    max-width: 900px;
    margin: 0 auto;
    width: 95%;
    position: relative;

    .game-title {
      margin-top: 80px;
      margin-bottom: 30px;
    }

    .terms {
      display: flex;
      flex-direction: column;
      gap: 10px;

      .term {
        .circle-wrapper {
          margin-right: -50px;

          z-index: 1;
          background: #2b2b4b;
          border: 4px solid #d7510b;
          border-radius: 50%;
          width: 80px;
          height: 80px;
          display: flex;
          justify-content: center;
          align-items: center;
          position: absolute;
          left: 10px;

          .circle {
            border: 2px solid #d7510b;
            border-radius: 50%;
            width: 60px;
            height: 60px;
            font-size: 50px;
            font-family: Wave;
            display: flex;
            justify-content: center;
            align-items: center;
            color: #ffffff;
          }
        }

        .term-text {
          min-height: 80px;
          width: calc(100% - 40px);
          border-radius: 10px;
          background: #2b2b4b;
          min-width: 20px;
          justify-content: center;
          align-items: center;
          display: flex;
          color: #ffffff;
          padding: 20px 20px 20px 80px;
          margin-left: 40px;
        }
      }
    }
  }
}

.section-product {
  width: 95%;
  min-height: 70vh;
  margin: 0 auto;
  padding: 50px 0 80px 0;
  /* position: relative; */
  .title {
    position: relative;

    &:after {
      content: "";
      position: absolute;
      height: 1px;
      width: 100%;
      left: 0;
      margin-top: 20px;
      background-color: rgb(214, 214, 214);
    }
  }

  .subintro {
    font-size: 16px;
    width: 100%;
    margin: auto;
    font-weight: 100;
    color: #190f25;
  }

  .item-group {
    padding-top: 50px;
    width: 100%;
    margin: 0 auto;
    display: grid;
    grid-gap: 20px;
    grid-template-columns: 1fr 1fr 1fr;

    &:last-child {
      padding-top: 30px;
    }
  }

  .set {
    margin: auto;
    width: 100%;
  }

  .items {
    position: relative;
    cursor: pointer;
    width: 100%;
    height: 340px;
    margin: auto;
    overflow: hidden;

    .theme {
      overflow: hidden;

      img {
        width: 100%;
        vertical-align: middle;
        margin-top: 70px;
        border-radius: 20px 20px 0 0;
      }
    }

    .main-object {
      position: absolute;
      top: 0;
      right: 0px;
      height: 225px;
      overflow: hidden;
      transform: translateY(0px);
      transition: 0.3s;

      img {
        vertical-align: middle;
        width: 100%;
      }
    }

    &:hover .main-object {
      position: absolute;
      transform: translateX(-25px);
    }

    .sub-object {
      display: none;
      position: absolute;
      top: 0;
      left: 10px;
      height: 225px;
      overflow: hidden;
      transform: translateY(0px);
      transition: 0.3s;

      img {
        vertical-align: middle;
        width: 100%;
      }
    }

    .txt {
      position: absolute;
      bottom: 0px;
      background: #2b2b4b;
      padding: 20px 80px 20px 20px;
      color: #fff;
      width: 100%;
      filter: brightness(0.9);
      border-radius: 0 0 20px 20px;

      p {
        font-size: 12px;
        font-weight: normal;
        font-stretch: normal;
        line-height: 16px;
      }

      img {
        max-width: 50%;
        margin: 0 0 10px;
        display: block;
        max-height: 30px;
      }
    }

    &:hover {
      .txt {
        opacity: 1;
        filter: brightness(1);
      }
    }
  }
}

.section-product .item-group {
  grid-template-columns: 1fr;
}

.vip-program {
  display: none;
}

.vip-container {
  .banner-container {
    background-position: 70% 50%;

    .btn-wrapper {
      .center {
        max-width: 300px;
        width: 100%;
        margin: 0 auto;

        .page-headline {
          font-size: 5rem;
          line-height: 5rem;
        }

        .page-blend {
          font-size: 1.7rem;
          line-height: 1.7rem;
          padding: 10px;
        }

        .page-subline {
          font-size: 1rem;
          line-height: 1rem;
        }

        .page-liner {
          font-size: 0.7rem;
          line-height: 1rem;
        }
      }
    }
  }

  .vipitem {
    background-size: cover;
    min-width: 340px;
    margin: auto;

    .vipcontents {
      padding-bottom: 10px;
    }
  }

  .inner-vip-mobile {
    margin-top: 20px;
    display: block;

    .note {
      margin-top: 10px;
    }

    .rebates {
      display: grid;
      width: 100%;
      gap: 10px;

      .rebate {
        background: #212534;
        border-top: 5px solid #dc5e43;
        border-bottom: 5px solid #dc5e43;
        border-radius: 20px;

        .name {
          font-size: 12px;
          line-height: 15px;
          color: #ffffff;
          padding: 20px 0;
        }

        .value {
          background: #2b2b4b;
          color: #ffffff;
          margin: 20px 0 0;
          font-family: Wave;
          font-size: 30px;
        }
      }
    }

    .note {
      color: #db7d42;
      font-size: 12px;
      text-align: left;
      padding: 0 10px;
      display: block;
    }
  }
}

